AND( OR( ISPICKVAL(Case_Type__c, "Teleclaim"), ISPICKVAL(Case_Type__c, "No Claim Bonus"), ISPICKVAL(Case_Type__c, "Others"), ISPICKVAL(Case_Type__c, "ICF Survey Inquiry"), ISPICKVAL(Case_Type__c, "ICF Survey Claim"), ISPICKVAL(Case_Type__c, "Withdrawal"), ISPICKVAL(Case_Type__c, "Collection"), ISPICKVAL(Case_Type__c, "Adhoc"), ISPICKVAL(Case_Type__c, "DMU") ), LEN(Call_Remarks__c) >= 8000 )
)
